package streaming

import (
	"context"
	"io"
)

// Header represents streaming headers as a simple string map.
// Keys are case-insensitive and normalized to lowercase.
type Header map[string]string

// Trailer represents streaming trailers as a simple string map.
// Keys are case-insensitive and normalized to lowercase.
type Trailer map[string]string

// ClientStream represents the client-side streaming interface.
type ClientStream interface {
	// Context returns the context for this stream.
	Context() context.Context

	// SendMsg sends a message on the stream.
	// It blocks until the message is sent or an error occurs.
	SendMsg(m interface{}) error

	// RecvMsg receives a message from the stream.
	// It blocks until a message is available or an error occurs.
	// Returns io.EOF when the stream is closed by the server.
	RecvMsg(m interface{}) error

	// CloseSend closes the send direction of the stream.
	// After calling CloseSend, no more messages can be sent.
	CloseSend() error

	// Header returns the header metadata from the server.
	// It blocks if the header has not been received yet.
	Header() (Header, error)

	// Trailer returns the trailer metadata from the server.
	// It must only be called after RecvMsg returns io.EOF.
	Trailer() Trailer
}

// ServerStream represents the server-side streaming interface.
type ServerStream interface {
	// Context returns the context for this stream.
	Context() context.Context

	// SendMsg sends a message on the stream.
	// It blocks until the message is sent or an error occurs.
	SendMsg(m interface{}) error

	// RecvMsg receives a message from the stream.
	// It blocks until a message is available or an error occurs.
	// Returns io.EOF when the stream is closed by the client.
	RecvMsg(m interface{}) error

	// SetHeader sets the header metadata to be sent to the client.
	// It can be called multiple times before SendHeader or the first SendMsg.
	// All provided metadata will be merged.
	SetHeader(Header) error

	// SendHeader sends the header metadata to the client.
	// It can only be called once and must be called before the first SendMsg.
	SendHeader(Header) error

	// SetTrailer sets the trailer metadata to be sent to the client.
	// It can be called multiple times.
	// The trailer will be sent when the stream is closed.
	SetTrailer(Trailer)
}

// ClientStreamWrapper wraps a Stream into a ClientStream.
type ClientStreamWrapper struct {
	stream Stream
}

// NewClientStreamWrapper creates a ClientStreamWrapper from a Stream.
func NewClientStreamWrapper(s Stream) *ClientStreamWrapper {
	return &ClientStreamWrapper{stream: s}
}

// Context returns the context for this stream.
func (w *ClientStreamWrapper) Context() context.Context {
	return w.stream.Context()
}

// SendMsg sends a message on the stream.
func (w *ClientStreamWrapper) SendMsg(m interface{}) error {
	return w.stream.SendMsg(m)
}

// RecvMsg receives a message from the stream.
func (w *ClientStreamWrapper) RecvMsg(m interface{}) error {
	return w.stream.RecvMsg(m)
}

// CloseSend closes the send direction of the stream.
func (w *ClientStreamWrapper) CloseSend() error {
	return w.stream.Close()
}

// Header returns the header metadata from the server.
func (w *ClientStreamWrapper) Header() (Header, error) {
	md, err := w.stream.Header()
	if err != nil {
		return nil, err
	}
	return mdToHeader(md), nil
}

// Trailer returns the trailer metadata from the server.
func (w *ClientStreamWrapper) Trailer() Trailer {
	md := w.stream.Trailer()
	return mdToTrailer(md)
}

// ServerStreamWrapper wraps a Stream into a ServerStream.
type ServerStreamWrapper struct {
	stream Stream
}

// NewServerStreamWrapper creates a ServerStreamWrapper from a Stream.
func NewServerStreamWrapper(s Stream) *ServerStreamWrapper {
	return &ServerStreamWrapper{stream: s}
}

// Context returns the context for this stream.
func (w *ServerStreamWrapper) Context() context.Context {
	return w.stream.Context()
}

// SendMsg sends a message on the stream.
func (w *ServerStreamWrapper) SendMsg(m interface{}) error {
	return w.stream.SendMsg(m)
}

// RecvMsg receives a message from the stream.
func (w *ServerStreamWrapper) RecvMsg(m interface{}) error {
	return w.stream.RecvMsg(m)
}

// SetHeader sets the header metadata to be sent to the client.
func (w *ServerStreamWrapper) SetHeader(h Header) error {
	return w.stream.SetHeader(headerToMD(h))
}

// SendHeader sends the header metadata to the client.
func (w *ServerStreamWrapper) SendHeader(h Header) error {
	return w.stream.SendHeader(headerToMD(h))
}

// SetTrailer sets the trailer metadata to be sent to the client.
func (w *ServerStreamWrapper) SetTrailer(t Trailer) {
	w.stream.SetTrailer(trailerToMD(t))
}

// mdToHeader converts metadata.MD to Header (single-value map).
// If a key has multiple values, only the first value is used.
func mdToHeader(md interface{}) Header {
	if md == nil {
		return Header{}
	}
	// md is metadata.MD which is map[string][]string
	mdMap, ok := md.(map[string][]string)
	if !ok {
		return Header{}
	}

	h := make(Header, len(mdMap))
	for k, v := range mdMap {
		if len(v) > 0 {
			h[k] = v[0]
		}
	}
	return h
}

